// ---- host logic: examples/api_tours/network_devtools/host.cpp ----
// API tour (C++ Wrapper): HTTP client and in-process DevTools. Same page, checks and case as
// examples/c/ports/kui_api_network_devtools.c (and the Go / Rust ports): the host fetches from the
// window's own DevTools server (a loopback HTTP server: /json/version) with the sync, worker-thread
// and main-thread request methods of kui::HttpClient, provokes transport errors (closed port,
// malformed URL, cancel), runs raw CDP commands, injects mouse / key / IME input and reads box
// models. No internet access is needed. One #tour-log row per check; #tour-result ends as
// "PASS n/n" once every asynchronous answer is in. The panel buttons repeat the calls.
//
// Document::dispatchDevToolsCommand / dispatchMouse / dispatchKey / dispatchIme / boxModel wrap the
// in-process DevTools calls. The small-buffer check of dispatch_command (a C contract the Wrapper's
// String result hides) still calls the C function through document.cHandle().
// Wrapper shapes that differ from the C port:
//   * A failed request still answers with a Response (statusCode 0, error set); a NULL response
//     (dropped at shutdown) never reaches the callback.
//   * kui::HttpClient keeps its C handle private; the clients live until the process exits
//     (like the C port, which never releases them).

#include <cstdio>
#include <cstring>
#include <functional>
#include <memory>
#include <sstream>

namespace {

kui::Document* g_doc = nullptr;
kui::Window* g_window = nullptr;

// ---- Self-check bookkeeping: count, log one <tr> per check, publish the verdict ----------
// check():  a documented behaviour; a failure makes the tour FAIL.
// known():  a documented behaviour the engine currently gets wrong (reported bug).

int g_total = 0;
int g_failed = 0;
int g_known = 0;
bool g_finished = false;
std::string g_failed_names;

template <typename... Parts>
std::string cat(const Parts&... parts) {
    std::ostringstream out;
    out.setf(std::ios::fixed);
    out.precision(1);
    (out << ... << parts);
    return out.str();
}

void log_row(const std::string& name, const std::string& result, const std::string& cell) {
    kui::Element* log = g_doc->getElementById("tour-log");
    if (!log) return;
    auto row = g_doc->createElement("tr");
    row->setAttribute("data-check", name);
    row->setAttribute("data-result", result);
    if (result != "ok") row->addClass("bad");
    auto first = g_doc->createElement("td");
    first->setTextContent(name);
    row->appendChild(first);
    auto second = g_doc->createElement("td");
    second->setTextContent(cell);
    row->appendChild(second);
    log->appendChild(row);
}

void check(const std::string& name, bool ok, const std::string& detail) {
    g_total++;
    if (ok) {
        log_row(name, "ok", "ok");
        return;
    }
    g_failed++;
    g_failed_names += (g_failed_names.empty() ? "" : ", ") + name;
    std::fprintf(stderr, "tour check failed: %s: %s\n", name.c_str(), detail.c_str());
    log_row(name, "fail", "FAIL: " + detail);
}

[[maybe_unused]] void known(const std::string& name, bool ok, const std::string& bug, const std::string& detail) {
    if (ok) {
        g_total++;
        log_row(name, "ok", "ok");
        return;
    }
    g_known++;
    std::fprintf(stderr, "tour known bug: %s: %s\n", name.c_str(), detail.c_str());
    log_row(name, "known", "KNOWN BUG: " + bug + " (" + detail + ")");
}

void finish() {
    if (g_finished) return;
    g_finished = true;
    kui::Element* result = g_doc->getElementById("tour-result");
    if (!result) return;
    std::string text = g_failed == 0 ? cat("PASS ", g_total, "/", g_total)
                                     : cat("FAIL ", g_failed, "/", g_total, ": ", g_failed_names);
    if (g_known) text += cat(" (known bugs: ", g_known, ")");
    result->setTextContent(text);
    result->setAttribute("data-total", std::to_string(g_total));
    result->setAttribute("data-failed", std::to_string(g_failed));
    result->setAttribute("data-known", std::to_string(g_known));
    result->addClass(g_failed == 0 ? "pass" : "fail");
}

// A Wrapper method that throws (kui::Error) fails its group instead of aborting the tour.
void run_group(const char* group, const std::function<void()>& body) {
    try {
        body();
    } catch (const std::exception& error) {
        check(cat(group, ".exception"), false, error.what());
    }
}

// Asynchronous checks still waiting for their callback; the verdict is published when the last
// one arrives (or by the watchdog, which fails whatever is still missing).
int g_pending = 0;
bool g_ready_done = false;

void settle() {
    if (--g_pending == 0 && g_ready_done) finish();
}

kui::Element* by_id(const char* id) { return g_doc->getElementById(id); }

void set_text(const char* id, const std::string& text) {
    if (kui::Element* element = by_id(id)) element->setTextContent(text);
}

bool has(const std::string& text, const char* part) { return text.find(part) != std::string::npos; }

// ---- Response readers ----------------------------------------------------------------------

struct Reply {
    int status = 0;
    std::string content_type;
    std::string error;
    std::string body;        // first 599 bytes, like the C port's buffer
    std::size_t body_len = 0;
};

Reply take_reply(const kui::HttpClient::Response& response) {
    Reply reply;
    reply.status = response.statusCode;
    reply.content_type = response.contentType;
    reply.error = response.error;
    reply.body_len = response.body.size();
    reply.body.assign(response.body.begin(), response.body.end());
    if (reply.body.size() > 599) reply.body.resize(599);
    return reply;
}

bool is_json_version(const Reply& reply) {
    return reply.status == 200 && has(reply.content_type, "application/json") && !reply.body.empty() &&
           reply.body[0] == '{' && has(reply.body, "\"Browser\":\"KUI/") && reply.error.empty();
}

void show_reply(const std::string& prefix, const Reply& reply) {
    set_text("http-out", cat(prefix, " status=", reply.status, " type=",
                             reply.content_type.empty() ? std::string("-") : reply.content_type,
                             " bytes=", reply.body_len, reply.error.empty() ? "" : " error=", reply.error));
    set_text("http-body", reply.body.empty() ? std::string("-") : reply.body);
}

// ---- HTTP against the loopback DevTools server ---------------------------------------------

kui::HttpClient* g_client = nullptr;         // lives until the process exits
kui::HttpClient* g_cancel_client = nullptr;
std::string g_version_url;
const char* const k_closed_url = "http://127.0.0.1:1/";   // nothing listens on port 1

// Worker-thread fetch: the callback runs on an HTTP worker thread, so it only copies the reply
// and hands it to the main thread with Platform::postToMainThread.
bool start_worker_fetch(kui::HttpClient& client, const std::string& url, const std::string& name,
                        bool self_check) {
    try {
        client.fetchAsync(url, [name, self_check](kui::HttpClient::Response response) {
            Reply reply = take_reply(response);
            kui::Platform::postToMainThread([name, self_check, reply] {
                if (!self_check) {
                    show_reply("worker + cancel_all:", reply);
                    return;
                }
                if (name == "http.fetch_async") {
                    check(name, is_json_version(reply), cat("status ", reply.status, " type '", reply.content_type,
                                                             "' error '", reply.error, "'"));
                } else {
                    check(name, reply.status == 0 && !reply.error.empty(),
                          cat("status ", reply.status, " error '", reply.error, "'"));
                }
                settle();
            });
        }, 3.0);
        return true;
    } catch (const kui::Error&) {
        return false;
    }
}

// Main-thread requests; false when the request was not accepted.
bool start_main_fetch(const std::string& url, std::function<void(const Reply&)> done) {
    try {
        g_client->fetchAsyncOnMainThread(url, [done](kui::HttpClient::Response response) {
            done(take_reply(response));
        }, 3.0);
        return true;
    } catch (const kui::Error&) {
        return false;
    }
}

void check_http() {
    g_client = new kui::HttpClient();
    check("http.client_create", g_client != nullptr, "no client");
    KuiStatus status = KUI_OK;
    try {
        g_client->setUserAgent("kui-api-tour/1.0");
    } catch (const kui::Error& error) {
        status = error.status();
    }
    check("http.set_user_agent", status == KUI_OK, cat("status ", static_cast<int>(status)));
    g_cancel_client = new kui::HttpClient();

    Reply reply = take_reply(g_client->fetchSync(g_version_url, 3.0));
    check("http.fetch_sync", is_json_version(reply),
          cat("http ", reply.status, " type '", reply.content_type, "' error '", reply.error, "'"));
    check("http.response_get_content_type", reply.content_type == "application/json",
          cat("content type '", reply.content_type, "'"));

    reply = take_reply(g_client->fetchSync("not a url", 3.0));
    check("http.response_get_error-bad-url", reply.status == 0 && !reply.error.empty(),
          cat("http ", reply.status, " error '", reply.error, "'"));
    check("http.response_get_body-empty-on-error", reply.body_len == 0, cat("body of ", reply.body_len, " bytes"));

    if (start_main_fetch(g_version_url, [](const Reply& answer) {
            check("http.fetch_async_on_main_thread", g_ready_done && is_json_version(answer),
                  cat("after ready ", g_ready_done ? 1 : 0, ", status ", answer.status, " type '",
                      answer.content_type, "' error '", answer.error, "'"));
            show_reply("GET /json/version (main thread):", answer);
            settle();
        })) {
        g_pending++;
    } else {
        check("http.fetch_async_on_main_thread", false, "request not accepted");
    }
    if (start_main_fetch(k_closed_url, [](const Reply& answer) {
            check("http.response_get_error-closed-port",
                  answer.status == 0 && !answer.error.empty() && answer.body_len == 0,
                  cat("status ", answer.status, " error '", answer.error, "' bytes ", answer.body_len));
            settle();
        })) {
        g_pending++;
    } else {
        check("http.response_get_error-closed-port", false, "request not accepted");
    }
    if (start_worker_fetch(*g_client, g_version_url, "http.fetch_async", true)) {
        g_pending++;
    } else {
        check("http.fetch_async", false, "request not accepted");
    }
    // A request that is cancelled right away still answers once, with the error set.
    if (start_worker_fetch(*g_cancel_client, k_closed_url, "http.cancel_all", true)) {
        g_pending++;
        try {
            g_cancel_client->cancelAll();
        } catch (const kui::Error& error) {
            check("http.cancel_all-status", false, cat("status ", static_cast<int>(error.status())));
        }
    } else {
        check("http.cancel_all", false, "request not accepted");
    }
}

// ---- DevTools: port, raw CDP commands -------------------------------------------------------

kui::u16 g_port = 0;

void devtools_port() {
    kui::DevToolsServer* server = g_window->devToolsServer();
    if (!server || !server->isRunning()) {
        // Not started by the runner (KUI_EXAMPLE_DEVTOOLS_PORT unset): start one, port 0 picks
        // a free one.
        server = g_window->startDevTools(0);
    }
    g_port = server ? server->port() : 0;
    g_version_url = cat("http://127.0.0.1:", g_port, "/json/version");
}

// The status of a Wrapper call: OK, or the C status carried by the kui::Error it throws.
template <typename Fn>
KuiStatus status_of(Fn&& fn) {
    try {
        fn();
        return KUI_OK;
    } catch (const kui::Error& error) {
        return error.status();
    }
}

// Runs a CDP command; the response (possibly truncated) lands in `out`. Used by the small-buffer
// check only: Document::dispatchDevToolsCommand returns the whole response as a String.
KuiStatus cdp(const char* json, char* buf, std::size_t capacity, std::size_t* out_len) {
    *out_len = 0;
    buf[0] = '\0';
    return kui_devtools_dispatch_command(g_doc->cHandle(), json, buf, capacity, out_len);
}

void check_devtools_commands() {
    char response[2048];
    char small[8];
    std::size_t length = 0;
    const std::string env_port = tour_env("KUI_EXAMPLE_DEVTOOLS_PORT");

    check("dt.window_get_devtools_port",
          g_port != 0 && (env_port.empty() || std::atoi(env_port.c_str()) == static_cast<int>(g_port)),
          cat("port ", g_port, " (KUI_EXAMPLE_DEVTOOLS_PORT=", env_port, ")"));

    std::string text;
    KuiStatus status = status_of([&] {
        text = g_doc->dispatchDevToolsCommand(
            "{\"id\":1,\"method\":\"DOM.setAttribute\",\"params\":{\"selector\":\"#cdp-target\","
            "\"name\":\"data-cdp\",\"value\":\"via-command\"}}");
    });
    kui::Element* target = by_id("cdp-target");
    const std::string attr = target ? target->getAttribute("data-cdp") : std::string();
    check("dt.dispatch_command", status == KUI_OK && has(text, "\"id\":1") && !has(text, "\"error\"") &&
          attr == "via-command",
          cat("status ", static_cast<int>(status), " attr '", attr, "' response ", text.substr(0, 120)));

    status = status_of([&] { text = g_doc->dispatchDevToolsCommand("{\"id\":2,\"method\":\"Nope.nothing\"}"); });
    check("dt.dispatch_command-unknown-method", status == KUI_OK && has(text, "\"error\""),
          cat("status ", static_cast<int>(status), " response ", text.substr(0, 120)));

    status = cdp("{\"id\":3,\"method\":\"Page.getLayoutMetrics\"}", small, sizeof small, &length);
    check("dt.dispatch_command-buffer-too-small", status == KUI_ERR_BUFFER_TOO_SMALL && length >= sizeof small,
          cat("status ", static_cast<int>(status), " length ", length));
}

// ---- DevTools token check: off for tools that cannot pass the token, then on again -------------

void check_token_auth() {
    kui::DevToolsServer* server = g_window->devToolsServer();
    if (!server) {
        check("dt.set_devtools_token_auth", false, "the DevTools server is not running");
        return;
    }
    std::string error;
    try {
        server->setTokenAuth(false);
        server->setTokenAuth(true);
    } catch (const kui::Error& thrown) {
        error = thrown.what();
    }
    check("dt.set_devtools_token_auth", error.empty(), cat("error '", error, "'"));
}

// ---- Input injection: listeners record what arrives ----------------------------------------

int g_clicks = 0;
int g_wheels = 0;
float g_move_x = 0, g_move_y = 0;
std::string g_first_key;
std::string g_first_code;
bool g_shift_seen = false;

void bind_listeners() {
    if (kui::Element* target = by_id("inj-target")) {
        target->addEventListener("click", [] { set_text("inj-target", cat("clicks=", ++g_clicks)); });
    }
    if (kui::Element* box = by_id("wheel-box")) {
        box->addEventListener("wheel", [] { set_text("wheel-box", cat("wheel=", ++g_wheels)); });
        box->addEventListener("mousemove", [](kui::MouseEvent& event) {
            g_move_x = event.clientX();
            g_move_y = event.clientY();
        });
    }
    if (kui::Element* input = by_id("inj-input")) {
        input->addEventListener("keydown", [](kui::KeyboardEvent& event) {
            if (g_first_key.empty()) {
                g_first_key = event.key();
                g_first_code = event.code();
            }
            if (event.shiftKey()) g_shift_seen = true;
        });
    }
}

void center_of(const char* id, float* x, float* y) {
    kui::Element* element = by_id(id);
    const kui::Rect rect = element ? element->boundingClientRect() : kui::Rect{};
    *x = rect.x + rect.width * 0.5f;
    *y = rect.y + rect.height * 0.5f;
}

void focus(const char* id) {
    if (kui::Element* element = by_id(id)) element->focus();
}

// Gap shared with the other tours: no Wrapper reader for an <input>'s current value; the page's
// Lua engine reads it.
std::string input_value(const char* id) {
    if (!tour_script) return {};
    const kui::ScriptResult result = tour_script->eval(cat("return document:getElementById('", id, "').value"));
    return result.success ? result.value.asString() : std::string();
}

KuiStatus inject_mouse(KuiCMouseEventType type, float x, float y, KuiCMouseButton button, int clicks,
                       float delta_y) {
    return status_of([&] { g_doc->dispatchMouse(type, x, y, button, 0, clicks, 0.0f, delta_y); });
}

void inject_click(const char* id) {
    float x, y;
    center_of(id, &x, &y);
    inject_mouse(KUI_C_MOUSE_PRESSED, x, y, KUI_C_MOUSE_BUTTON_LEFT, 1, 0.0f);
    inject_mouse(KUI_C_MOUSE_RELEASED, x, y, KUI_C_MOUSE_BUTTON_LEFT, 1, 0.0f);
}

void inject_wheel() {
    float x, y;
    center_of("wheel-box", &x, &y);
    inject_mouse(KUI_C_MOUSE_WHEEL, x, y, KUI_C_MOUSE_BUTTON_NONE, 0, 120.0f);
}

// Key down / char / key up for each letter, as a keyboard would.
void inject_text(const char* letters) {
    for (; *letters; ++letters) {
        const std::string key(1, *letters);
        char code[8];
        std::snprintf(code, sizeof code, "Key%c", *letters - 'a' + 'A');
        g_doc->dispatchKey(KUI_C_KEY_DOWN, key, code);
        g_doc->dispatchKey(KUI_C_KEY_CHAR, key, code, 0, key);
        g_doc->dispatchKey(KUI_C_KEY_UP, key, code);
    }
}

// Start, an intermediate composition, then the committed text ("ni" -> U+4F60).
void inject_ime() {
    g_doc->dispatchIme(KUI_C_IME_START);
    g_doc->dispatchIme(KUI_C_IME_UPDATE, "ni");
    g_doc->dispatchIme(KUI_C_IME_COMMIT, "\xe4\xbd\xa0");
}

bool close01(float a, float b) { return a - b < 0.01f && b - a < 0.01f; }

void check_injection() {
    inject_click("inj-target");
    check("dt.dispatch_mouse_event-click", g_clicks == 1, cat("clicks ", g_clicks));

    float x, y;
    center_of("wheel-box", &x, &y);
    KuiStatus status = inject_mouse(KUI_C_MOUSE_MOVED, x + 3.0f, y + 2.0f, KUI_C_MOUSE_BUTTON_NONE, 0, 0.0f);
    check("dt.dispatch_mouse_event-move",
          status == KUI_OK && close01(g_move_x, x + 3.0f) && close01(g_move_y, y + 2.0f),
          cat("status ", static_cast<int>(status), " moved to (", x + 3.0f, ", ", y + 2.0f, "), listener saw (",
              g_move_x, ", ", g_move_y, ")"));
    inject_wheel();
    check("dt.dispatch_mouse_event-wheel", g_wheels == 1, cat("wheel events ", g_wheels));
    status = inject_mouse(static_cast<KuiCMouseEventType>(9), 0.0f, 0.0f, KUI_C_MOUSE_BUTTON_NONE, 0, 0.0f);
    check("dt.dispatch_mouse_event-invalid-type", status == KUI_ERR_INVALID_ARG,
          cat("status ", static_cast<int>(status)));

    focus("inj-input");
    inject_text("kui");
    std::string value = input_value("inj-input");
    check("dt.dispatch_key_event", value == "kui" && g_first_key == "k" && g_first_code == "KeyK",
          cat("value '", value, "', first keydown key '", g_first_key, "' code '", g_first_code, "'"));
    kui_devtools_dispatch_key_event(g_doc->cHandle(), KUI_C_KEY_DOWN, "Shift", 0, "ShiftLeft", 0, 8, nullptr, 0, 0);
    kui_devtools_dispatch_key_event(g_doc->cHandle(), KUI_C_KEY_UP, "Shift", 0, "ShiftLeft", 0, 8, nullptr, 0, 0);
    check("dt.dispatch_key_event-modifiers", g_shift_seen, "keydown listener saw no Shift");

    focus("ime-input");
    inject_ime();
    value = input_value("ime-input");
    check("dt.dispatch_ime_event", value == "\xe4\xbd\xa0", cat("value '", value, "'"));
}

// ---- Box model: four quads vs the bounding rect ---------------------------------------------

struct Quads {
    float q[32] = {};
    float width = 0, height = 0;
};

float quad_w(const Quads& b, int box) { return b.q[box * 8 + 2] - b.q[box * 8 + 0]; }
float quad_h(const Quads& b, int box) { return b.q[box * 8 + 5] - b.q[box * 8 + 1]; }
bool close_to(float a, float b) { return a - b < 0.5f && b - a < 0.5f; }

KuiStatus box_model(const char* selector, Quads& b) {
    const auto model = g_doc->boxModel(selector);
    if (!model) return KUI_ERR_NOT_FOUND;
    const std::array<kui::Point, 4>* boxes[4] = {&model->content, &model->padding, &model->border, &model->margin};
    for (int box = 0; box < 4; ++box) {
        for (int corner = 0; corner < 4; ++corner) {
            b.q[box * 8 + corner * 2] = (*boxes[box])[corner].x;
            b.q[box * 8 + corner * 2 + 1] = (*boxes[box])[corner].y;
        }
    }
    b.width = model->size.width;
    b.height = model->size.height;
    return KUI_OK;
}

void check_box_model() {
    Quads b;
    KuiStatus status = box_model("#box-target", b);
    kui::Element* element = by_id("box-target");
    const kui::Rect rect = element ? element->boundingClientRect() : kui::Rect{};
    check("dt.get_box_model", status == KUI_OK && close_to(b.width, 120.0f) && close_to(b.height, 40.0f) &&
          close_to(quad_w(b, 1), 140.0f) && close_to(quad_w(b, 2), 148.0f) && close_to(quad_h(b, 2), 68.0f) &&
          close_to(quad_w(b, 3), 160.0f) && close_to(b.q[0] - b.q[16], 14.0f),
          cat("status ", static_cast<int>(status), " content ", b.width, "x", b.height, " padding ", quad_w(b, 1),
              " border ", quad_w(b, 2), "x", quad_h(b, 2), " margin ", quad_w(b, 3)));
    check("dt.get_box_model-vs-bounding-rect",
          close_to(b.q[16], rect.x) && close_to(b.q[17], rect.y) && close_to(quad_w(b, 2), rect.width) &&
          close_to(quad_h(b, 2), rect.height),
          cat("border quad (", b.q[16], ", ", b.q[17], ") vs rect (", rect.x, ", ", rect.y, " ", rect.width, "x",
              rect.height, ")"));
    Quads missing;
    status = box_model("#no-such-box", missing);
    check("dt.get_box_model-missing", status == KUI_ERR_NOT_FOUND, cat("status ", static_cast<int>(status)));
}

// ---- Panel buttons --------------------------------------------------------------------------

void show_cdp(const char* json) {
    char response[2048];
    std::size_t length = 0;
    const KuiStatus status = cdp(json, response, sizeof response, &length);
    set_text("cdp-out", cat("status=", static_cast<int>(status), " ", std::string(response).substr(0, 300)));
}

void on_http_main() {
    start_main_fetch(g_version_url, [](const Reply& reply) { show_reply("GET (main thread):", reply); });
}

void on_http_sync() {
    Reply reply;
    try {
        reply = take_reply(g_client->fetchSync(g_version_url, 3.0));
    } catch (const kui::Error& error) {
        reply.error = error.what();
    }
    show_reply("GET (sync):", reply);
}

void on_http_closed() {
    start_main_fetch(k_closed_url, [](const Reply& reply) { show_reply("closed port:", reply); });
}

void on_http_bad() {
    Reply reply;
    try {
        reply = take_reply(g_client->fetchSync("not a url", 3.0));
    } catch (const kui::Error& error) {
        reply.error = error.what();
    }
    show_reply("bad URL:", reply);
}

void on_http_cancel() {
    if (start_worker_fetch(*g_cancel_client, k_closed_url, "button", false)) g_cancel_client->cancelAll();
}

void on_inj_click() {
    inject_click("inj-target");
    set_text("inj-out", cat("injected click -> clicks=", g_clicks));
}

void on_inj_type() {
    focus("inj-input");
    inject_text("kui");
    set_text("inj-out", "typed -> value=" + input_value("inj-input"));
}

void on_inj_ime() {
    focus("ime-input");
    inject_ime();
    set_text("inj-out", "IME -> value=" + input_value("ime-input"));
}

void on_inj_wheel() {
    inject_wheel();
    set_text("inj-out", cat("injected wheel -> wheel=", g_wheels));
}

std::string whole(float value) {
    char buf[32];
    std::snprintf(buf, sizeof buf, "%.0f", static_cast<double>(value));
    return buf;
}

void on_box() {
    Quads b;
    box_model("#box-target", b);
    kui::Element* element = by_id("box-target");
    const kui::Rect rect = element ? element->boundingClientRect() : kui::Rect{};
    set_text("box-out", cat("content=", whole(b.width), "x", whole(b.height), " padding=", whole(quad_w(b, 1)), "x",
                            whole(quad_h(b, 1)), " border=", whole(quad_w(b, 2)), "x", whole(quad_h(b, 2)),
                            " margin=", whole(quad_w(b, 3)), "x", whole(quad_h(b, 3)), " | rect=",
                            whole(rect.width), "x", whole(rect.height)));
}

// Fails whatever asynchronous check has not answered within 2.6 s, then publishes.
void watchdog() {
    if (g_finished) return;
    if (g_pending > 0) check("http.async-answers", false, cat(g_pending, " request(s) never answered"));
    finish();
}

// Clicks on #id run `handler` (a missing button is reported as a failed check).
void on_click(const char* id, void (*handler)()) {
    kui::Element* button = by_id(id);
    if (!button) {
        check(cat("ui.", id), false, "button missing");
        return;
    }
    button->addEventListener("click", [handler](kui::Event&) {
        try {
            handler();
        } catch (const std::exception& error) {
            std::fprintf(stderr, "kui_api_network_devtools: %s\n", error.what());
        }
    });
}

}  // namespace

void tour_ready(kui::Window& window, kui::Document& document) {
    g_doc = &document;
    g_window = &window;

    bind_listeners();
    devtools_port();
    run_group("http", check_http);
    run_group("dt", check_devtools_commands);
    run_group("dt", check_token_auth);
    run_group("dt", check_injection);
    run_group("dt", check_box_model);
    g_ready_done = true;
    if (g_pending == 0) finish();
    kui::Platform::setTimeout(watchdog, 2600);

    on_click("btn-http-main", on_http_main);
    on_click("btn-http-sync", on_http_sync);
    on_click("btn-http-closed", on_http_closed);
    on_click("btn-http-bad", on_http_bad);
    on_click("btn-http-cancel", on_http_cancel);
    on_click("btn-cdp-attr", [] {
        show_cdp("{\"id\":11,\"method\":\"DOM.setAttribute\",\"params\":{\"selector\":\"#cdp-target\","
                 "\"name\":\"data-cdp\",\"value\":\"button\"}}");
    });
    on_click("btn-cdp-metrics", [] { show_cdp("{\"id\":12,\"method\":\"Page.getLayoutMetrics\"}"); });
    on_click("btn-cdp-unknown", [] { show_cdp("{\"id\":13,\"method\":\"Nope.nothing\"}"); });
    on_click("btn-inj-click", on_inj_click);
    on_click("btn-inj-type", on_inj_type);
    on_click("btn-inj-ime", on_inj_ime);
    on_click("btn-inj-wheel", on_inj_wheel);
    on_click("btn-box", on_box);
}
// ---- end of examples/api_tours/network_devtools/host.cpp ----

int main() {
    try {
        if (!kui::Platform::init()) return 3;
        kui::WindowConfig config;
        config.title = "KUI API \xe2\x80\x94 HTTP client & DevTools commands";
        config.width = 1100;
        config.height = 780;
        auto window = kui::Window::create(config);
        if (!window) return 4;
        kui::Document* document = window->document();
        auto script = kui::ScriptEngine::create();
        if (script) {
            script->setErrorHandler([](const std::string& error, const std::string& source, int line) {
                std::fprintf(stderr, "[Lua] %s:%d: %s\n", source.c_str(), line, error.c_str());
            });
            script->bindDocument(document);
            window->setScriptEngine(script.get());
        }
        tour_script = script.get();
        document->loadHTML(k_tour_page);
        if (script) script->executeScripts();
        // Test hook shared with the C / Go / Rust runners: KUI_EXAMPLE_DEVTOOLS_PORT=<port> starts
        // DevTools so scripts/verify_example_ports.py can click and read the DOM.
        const std::string port = tour_env("KUI_EXAMPLE_DEVTOOLS_PORT");
        if (!port.empty()) window->startDevTools(static_cast<kui::u16>(std::atoi(port.c_str())));
        tour_ready(*window, *document);
        const int code = kui::Platform::run();
        tour_script = nullptr;
        return code;
    } catch (const std::exception& error) {
        std::fprintf(stderr, "[kui_api_network_devtools] %s\n", error.what());
        return 9;
    }
}
